from copy import deepcopy
from numbers import Real


class NearestLabelPlanner:
    def __init__(self, imu_indices, planning_distance, sequence_length, num_classes):
        if not isinstance(planning_distance, int) or isinstance(planning_distance, bool):
            raise ValueError("planning_distance must be an integer")
        if not isinstance(sequence_length, int) or isinstance(sequence_length, bool):
            raise ValueError("sequence_length must be an integer")
        if not isinstance(num_classes, int) or isinstance(num_classes, bool):
            raise ValueError("num_classes must be an integer")
        if planning_distance <= 0 or sequence_length <= 0 or num_classes <= 0:
            raise ValueError("sizes must be positive")
        if planning_distance > sequence_length:
            raise ValueError("planning_distance exceeds sequence_length")
        if isinstance(imu_indices, (str, bytes)):
            raise ValueError("imu_indices must be a non-string sequence")
        try:
            indices = tuple(imu_indices)
        except TypeError as exc:
            raise ValueError("imu_indices must be a sequence") from exc
        if not indices:
            raise ValueError("imu_indices cannot be empty")
        if any(not isinstance(i, int) or isinstance(i, bool) for i in indices):
            raise ValueError("sensor indices must be integers")
        if any(i < 0 for i in indices) or len(set(indices)) != len(indices):
            raise ValueError("sensor indices must be distinct and non-negative")
        self.imu_indices = indices
        self.planning_distance = planning_distance
        self.sequence_length = sequence_length
        self.num_classes = num_classes
        self._training_sequences = None
        self._training_labels = None

    def _validate(self, sequences, labels):
        try:
            sequence_list = list(sequences)
            label_list = list(labels)
        except TypeError as exc:
            raise TypeError("sequences and labels must be iterable") from exc
        if len(sequence_list) != len(label_list):
            raise ValueError("sequence and label counts differ")
        checked_sequences = []
        checked_labels = []
        for sequence, label_sequence in zip(sequence_list, label_list):
            try:
                rows = list(sequence)
                values = list(label_sequence)
            except TypeError as exc:
                raise TypeError("each sequence and label sequence must be iterable") from exc
            if len(rows) != self.sequence_length or len(values) != self.sequence_length:
                raise ValueError("incorrect sequence length")
            checked_rows = []
            for row in rows:
                try:
                    checked_row = list(row)
                except TypeError as exc:
                    raise TypeError("each sensor row must be iterable") from exc
                if any(i >= len(checked_row) for i in self.imu_indices):
                    raise ValueError("sensor row is missing a requested index")
                for i in self.imu_indices:
                    if not isinstance(checked_row[i], Real) or isinstance(checked_row[i], bool):
                        raise TypeError("sensor values must be real numbers")
                checked_rows.append(checked_row)
            if any(not isinstance(v, int) or isinstance(v, bool) for v in values):
                raise TypeError("labels must be integers")
            if any(v < 0 or v >= self.num_classes for v in values):
                raise ValueError("label outside class range")
            checked_sequences.append(checked_rows)
            checked_labels.append(values)
        return checked_sequences, checked_labels

    def fit(self, sequences, labels):
        checked_sequences, checked_labels = self._validate(sequences, labels)
        if not checked_sequences:
            raise ValueError("training data cannot be empty")
        self._training_sequences = deepcopy(checked_sequences)
        self._training_labels = deepcopy(checked_labels)

    def infer(self, sequences, targets):
        checked_sequences, checked_targets = self._validate(sequences, targets)
        if not checked_sequences:
            return [], [], []
        if self._training_sequences is None:
            raise RuntimeError("planner has not been fitted")
        prefix_length = self.sequence_length - self.planning_distance
        predictions = []
        expected = []
        positions = []
        for query, target in zip(checked_sequences, checked_targets):
            best_index = None
            best_distance = None
            for index, candidate in enumerate(self._training_sequences):
                distance = sum(
                    (query[row][imu] - candidate[row][imu]) ** 2
                    for row in range(prefix_length)
                    for imu in self.imu_indices
                )
                if best_distance is None or distance <= best_distance:
                    best_distance = distance
                    best_index = index
            predictions.append(deepcopy(self._training_labels[best_index][-self.planning_distance:]))
            expected.append(deepcopy(target[-self.planning_distance:]))
            positions.append(list(range(prefix_length, self.sequence_length)))
        return predictions, expected, positions

